import csv
import openpyxl

# Load CFC data
cfc_data = {}
with open('/tmp/ecb_cfc.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        year = int(row['TIME_PERIOD'])
        cfc_data[year] = float(row['OBS_VALUE'])

# Load PWT data
wb = openpyxl.load_workbook('/root/pwt110.xlsx', read_only=True)
ws = wb['Data']
col_map = {}
for cell in ws[1]:
    if cell.value:
        col_map[cell.value] = cell.column

pwt_data = {}
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, values_only=False):
    cc = row[col_map['countrycode']-1].value
    if cc == 'GEO':
        year = row[col_map['year']-1].value
        rnna = row[col_map['rnna']-1].value
        delta = row[col_map['delta']-1].value
        if year:
            pwt_data[year] = {'rnna': rnna, 'delta': delta}

wb.close()

print(f"{'Year':>6} {'CFC(M GEL)':>12} {'rnna(M GEL)':>12} {'CFC/rnna':>10} {'PWT delta':>10}")
for year in range(1996, 2024):
    if year in cfc_data and year in pwt_data:
        cfc_m = cfc_data[year] / 1e6  # Convert to millions GEL
        rnna = pwt_data[year]['rnna']
        delta_pwt = pwt_data[year]['delta']
        ratio = cfc_m / rnna
        print(f"{year:>6} {cfc_m:>12.2f} {rnna:>12.2f} {ratio:>10.6f} {delta_pwt:>10.6f}")
